{
  "technical_and_design_decisions": [
    "Adopt Go modules to depend on external Hyperledger Fabric packages (e.g., github.com/hyperledger/fabric and github.com/hyperledger/fabric-protos) instead of vendored internal/third_party copies.",
    "Remove all copied/modified code from the SDK and replace with imports to the external packages, adapting SDK code to the external APIs without maintaining forks.",
    "For U6, implement a short-lived workaround in the chaincode packaging logic that honors go.mod files when present, guarded by a clear deprecation warning and easy removal path (e.g., a build flag or environment variable).",
    "Keep public SDK APIs stable; only internal implementation changes. If unavoidable breaking changes occur, document them in migration notes.",
    "Use the existing Fabric SDK Go test suite to validate changes; no new large test frameworks."
  ],
  "assumptions": [
    "External Fabric modules exposing the required packages (gossip/protoext, cauthdsl, ccprovider, ledger, common, core, configtxgen, configtxlator) are already published or will be published in a usable version before/with this work.",
    "The developer is already familiar with Hyperledger Fabric and Go module management, requiring no training.",
    "Existing automated tests cover the affected functionality sufficiently; effort includes only adapting tests to new imports, not writing extensive new tests.",
    "Effort estimates are for a single developer performing all tasks, including coding, local building, and testing, but exclude external code review delays and elapsed calendar time.",
    "The temporary workaround (U6) is expected to be removed in a subsequent release, so only minimal implementation and testing is needed."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Dependency analysis and Go module setup",
      "activity_description": "Analyze current internal/third_party copies and external Fabric modules, update go.mod to reference external packages, and set up local build environment.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Externalize gossip utilities (U1)",
      "activity_description": "Replace internal modified gossip/discovery client code with external github.com/hyperledger/fabric/gossip/protoext and related packages, adjust SDK discovery client usage, and fix compilation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Externalize cauthdsl utilities (U2)",
      "activity_description": "Remove third_party cauthdsl copy and update SDK to import external common/cauthdsl package; adapt any SDK-specific wrappers.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize ccprovider structures (U3)",
      "activity_description": "Remove third_party ccprovider copy and use external core/common/ccprovider structures; update references in SDK.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize ledger structures (U4)",
      "activity_description": "Remove third_party ledger copy and use external core/ledger packages; adapt SDK code to external ledger structures.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize common and core utilities (U5)",
      "activity_description": "Remove internal common and core utility copies and replace with external Fabric common/core packages; resolve API differences across the SDK.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize configtxgen functions (U7)",
      "activity_description": "Remove internal configtxgen copy and use external configtxgen functions; update resource/configtx.go and related SDK code.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "Externalize configtxlator functions (U8)",
      "activity_description": "Remove internal configtxlator copy and use external configtxlator functions; update SDK code accordingly.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Implement temporary go.mod workaround for chaincode package (U6)",
      "activity_description": "Add short-lived logic to honor go.mod files inside chaincode packages, with deprecation warning and easy removal, as a transition workaround.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration testing and build stabilization",
      "activity_description": "Run full SDK unit and integration test suites, fix import/build issues, ensure all tests pass with external dependencies, and verify CI build.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation and migration notes update",
      "activity_description": "Update SDK documentation, remove references to copied code, add migration notes for any breaking changes, and note the temporary go.mod workaround.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 33
  }
}

